from pathlib import Path
p=Path(__file__).parent
base='''@font-face{font-family:Baloo;src:url('../../../public/fonts/baloo-2-latin.woff2');font-weight:800}@font-face{font-family:VC;src:local('Futura-CondensedExtraBold')}*{box-sizing:border-box}html,body{margin:0;width:1280px;height:720px;overflow:hidden}body{position:relative;background:#080810;color:white;font-family:Baloo,sans-serif}img,.wash{position:absolute}h1,p{margin:0}h1{font-family:VC,'Arial Narrow',sans-serif;line-height:.94;font-weight:900;letter-spacing:-3px}.pill{position:absolute;background:#f5c518;color:#2a1a10;border-radius:80px;padding:5px 26px 8px;font:800 36px Baloo;left:48px;bottom:40px}.eyebrow{font:800 26px Baloo;letter-spacing:5px;position:absolute;left:48px;top:40px}.full{width:1280px;height:720px;object-fit:cover}.small{font:800 30px Baloo;letter-spacing:4px}'''
def page(n,css,body):
 (p/f't{n}.html').write_text(f'<!doctype html><html lang="ca"><meta charset="utf-8"><meta name="viewport" content="width=1280"><title>T{n} · Mulassa</title><style>{base}{css}</style><body>{body}</body></html>')
page(1,'''body{background:#f5c518;color:#22140c}.hero{height:720px;width:910px;object-fit:cover;right:0;filter:brightness(1.35) saturate(1.25);object-position:right}.wash{inset:0;background:linear-gradient(90deg,#f5c518 0%,#f5c518 37%,transparent 69%)}h1{position:absolute;left:48px;top:202px;font-size:174px;letter-spacing:-5px;transform:rotate(-4deg);text-shadow:4px 5px 0 #fff3b7}.eyebrow{top:64px}.pill{background:#23160e;color:#f5c518}''','''<img class="hero" src="frames/f073.png"><div class="wash"></div><p class="eyebrow">VALLS · TECHNO</p><h1>MULASSA!</h1><div class="pill">mulassa.cat</div>''')
page(2,''' .full{filter:brightness(1.55) saturate(1.35)}.wash{inset:0;background:linear-gradient(90deg,#130627 0%,#130627cc 28%,transparent 70%)}h1{position:absolute;left:48px;top:226px;font-size:232px;color:#fff;text-shadow:0 9px 0 #c70082,0 0 40px #ff00a8}.eyebrow{color:#71ffe8}''','''<img class="full" src="frames/f073.png"><div class="wash"></div><p class="eyebrow">MULASSA DE VALLS</p><h1>GUAPA!</h1><div class="pill">mulassa.cat</div>''')
page(3,''' .backdrop{position:absolute;inset:0;overflow:hidden}.full{left:480px;width:1280px;object-position:75% center;filter:saturate(1.6) brightness(1.2)}.wash{inset:0;background:linear-gradient(90deg,#07091df2, #07091d99 40%,transparent 75%)}h1{position:absolute;left:48px;top:126px;font-size:152px;line-height:1.14;color:#caff32;text-shadow:0 0 32px #87ff3260}h1 span{color:white}.eyebrow{color:#f6b1fa}.pill{bottom:40px}.beam{position:absolute;inset:0;background:linear-gradient(153deg,transparent 49.8%,#a6ff37 50%,transparent 50.2%);width:1280px;height:720px;clip-path:polygon(40% 0,100% 0,100% 40%,40% 40%)}''','''<div class="backdrop"><img class="full" src="frames/f081.png"></div><div class="wash"></div><div class="beam"></div><p class="eyebrow">MULASSA DE VALLS</p><h1>LA PLAÇA<br><span>ÉS TECHNO</span></h1><div class="pill">mulassa.cat</div>''')
page(4,''' .left,.right{position:absolute;top:0;height:720px;overflow:hidden}.left{left:0;width:480px;background:#111521}.right{left:480px;width:800px;background:#190519}.left img{height:720px;width:1280px;left:-380px;object-fit:cover;filter:grayscale(1) brightness(.85)}.right img{height:720px;width:1280px;left:-280px;filter:brightness(1.4) saturate(1.5)}.wash{inset:0;background:linear-gradient(#05040a99,transparent 45%,#05040ac0)}.slash{position:absolute;top:0;left:470px;width:10px;height:710px;background:#f5c518;transform:rotate(8deg)}h1{position:absolute;left:48px;top:68px;font-size:108px;color:white}h1 b{color:#f5c518;margin-left:135px}.arrow{position:absolute;left:413px;top:315px;border-radius:100%;background:#f5c518;color:#2a1a10;width:112px;height:112px;font:80px/100px sans-serif;text-align:center}''','''<div class="left"><img src="frames/f025.png"></div><div class="right"><img src="frames/f081.png"></div><div class="wash"></div><div class="slash"></div><h1>DE FESTA <b>A TECHNO</b></h1><div class="arrow">→</div><div class="pill">mulassa.cat</div>''')
page(5,''' .photo{position:absolute;width:850px;height:720px;right:0;overflow:hidden}.photo img{width:1280px;height:720px;left:-250px;filter:brightness(1.8)}.wash{inset:0;background:linear-gradient(90deg,#080a12 0%,#080a12 27%,transparent 62%)}h1{position:absolute;left:48px;top:177px;font-size:120px;letter-spacing:-3px}.tag{position:absolute;left:52px;top:439px;color:#f5c518;font:800 34px Baloo;letter-spacing:9px}.pill{font-size:36px}.line{position:absolute;top:144px;left:48px;width:80px;height:8px;background:#f5c518}''','''<div class="photo"><img src="frames/f010.png"></div><div class="wash"></div><div class="line"></div><h1>MULASSA<br>DE VALLS</h1><p class="tag">TECHNO</p><div class="pill">mulassa.cat</div>''')
ideas=[('El crit','MULASSA!','El nom ocupa el groc de marca i comparteix el focus amb el primer pla.'),('La guapa','GUAPA!','La crida de la cançó, en blanc i fúcsia, al costat de la cara.'),('La rave','LA PLAÇA ÉS TECHNO','Cartell nocturn amb verd àcid, làser i pista de ball.'),('El canvi','DE FESTA A TECHNO','Dues atmosferes del vídeo: focus sobri i explosió de color.'),('La figura','MULASSA DE VALLS · TECHNO','Retrat fosc i net amb el nom de la figura i la marca groga.')]
html='''<!doctype html><html lang="ca"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mulassa · 5 miniatures</title><style>@font-face{font-family:Baloo;src:url('../../../public/fonts/baloo-2-latin.woff2');font-weight:800}*{box-sizing:border-box}body{margin:0;background:#101019;color:#f8f5ee;font:16px/1.5 system-ui;padding:32px}header{max-width:1600px;margin:0 auto 32px}h1{font:800 40px Baloo;margin:0}p{margin:8px 0;color:#c5c3ce}.grid{display:grid;grid-template-columns:repeat(5,minmax(480px,1fr));gap:24px;align-items:start}article{background:#1c1c28;border:1px solid #333340;border-radius:16px;padding:24px}h2{font:800 28px Baloo;margin:0 0 8px}img{display:block;max-width:100%;height:auto}.large{width:100%;border-radius:8px}.sizes{display:flex;flex-wrap:wrap;align-items:start;gap:24px;margin-top:24px}figure{margin:0}figcaption{font-size:12px;color:#aaa6b6;margin-top:8px}.copy{color:#f5c518;font-weight:700}a{color:inherit}section{overflow-x:auto;padding-bottom:24px}</style><header><h1>Mulassa. Cinc maneres de fer-la sonar.</h1><p>Propostes de miniatura · 1280 × 720 · Comparació a 320 × 180 i 168 × 94. Desplaça't horitzontalment per comparar-les.</p></header><section><div class="grid">'''
for n,(name,copy,idea) in enumerate(ideas,1):
 html+=f'<article><h2>T{n} · {name}</h2><a href="t{n}.png"><img class="large" src="t{n}.png" alt="T{n}: {copy}"></a><p class="copy">{copy}</p><p>{idea}</p><div class="sizes"><figure><img src="t{n}.png" width="320" height="180"><figcaption>320 × 180</figcaption></figure><figure><img src="t{n}.png" width="168" height="94"><figcaption>168 × 94</figcaption></figure></div><p><a href="t{n}.html">HTML</a> · <a href="t{n}.png">PNG original</a></p></article>'
(p/'index.html').write_text(html+'</div></section></html>')
